  표5_매튜헨리: [
    {"영어원문": "Hazor shall be a dwelling for dragons, a desolation for ever; no man shall abide there. The curse of barrenness shall lie upon it.", "한국어번역": "하솔이 승냥이의 거처가 되어 영원히 황폐할 것이며, 아무도 거기에 거주하지 못할 것이다. 불모의 저주가 그 위에 놓일 것이다.", "핵심통찰": "영원한 불모의 저주는 하나님의 심판의 최종성과 되돌릴 수 없음을 보여준다"},
    {"영어원문": "Where sin has abounded, desolation shall abound. Those places that were filled with people shall be emptied and left to wild beasts.", "한국어번역": "죄가 넘친 곳에 황폐가 넘칠 것이다. 사람으로 가득했던 곳이 비워지고 야수들에게 넘겨질 것이다.", "핵심통찰": "죄의 풍성함과 황폐의 풍성함 사이의 비례 관계 - 죄가 클수록 심판도 크다"},
    {"영어원문": "This is the end of those who live without God in the world; their habitations shall be made a desolation.", "한국어번역": "이것이 이 세상에서 하나님 없이 사는 자들의 결말이다. 그들의 거처가 황폐하게 될 것이다.", "핵심통찰": "하나님 없는 삶의 궁극적 결말은 영원한 황폐이다"}
  ],
  표6_설교자료: [
    {"대지": "제목", "내용": "영원한 황폐의 경고", "예화_적용": "하솔의 영구적 멸망을 통해 하나님의 심판의 최종성과 회개의 시급성을 선포"},
    {"대지": "서론", "내용": "하솔의 마을들에서 더 이상 사람의 웃음소리가 들리지 않습니다. 아이들의 놀이 소리도, 상인들의 호객 소리도 없습니다. 오직 승냥이의 울음소리만 메아리칩니다. 영원히.", "예화_적용": "체르노빌 원전 사고 후 버려진 프리피야트 시가 40년째 무인도시로 남아있는 현실"},
    {"대지": "1대지", "내용": "승냥이의 처소 - 문명의 역전", "예화_적용": "인간이 건설한 위대한 도시들이 폐허가 되는 역사적 사례들(페트라, 앙코르와트 등)"},
    {"대지": "2대지", "내용": "영원한 황폐 - 돌이킬 수 없는 심판", "예화_적용": "지금 회개하지 않으면 돌이킬 수 없는 때가 온다. 히브리서 3:15 '오늘 너희가 그의 음성을 듣거든 마음을 완악하게 하지 말라'"},
    {"대지": "3대지", "내용": "거주 불가능 - 생명 없는 삶의 비유", "예화_적용": "하나님 없이 사는 삶은 겉으로 살아있지만 영적으로 사람이 살 수 없는 황폐한 곳과 같다(엡 2:1)"},
    {"대지": "결론", "내용": "하솔은 영원히 황폐해졌습니다. 그러나 여러분에게는 아직 기회가 있습니다. '오늘'이 은혜의 시간입니다. 영원한 황폐 대신 영원한 생명을 선택하십시오.", "예화_적용": "고린도후서 6:2 '보라 지금은 은혜 받을 만한 때요 보라 지금은 구원의 날이로다'"}
  ],
